args.command:
/bin/bash -lc "node --input-type=module <<'JS'
for (const stage of ['1', '2', '3']) {
  const response = await fetch('http://localhost:3000/product', {headers: {rsc: '1', 'next-router-prefetch': stage}})
  const body = await response.text()
  console.log(JSON.stringify({stage, status: response.status, type: response.headers.get('content-type'), relatedIncluded: body.includes('Compact Widget'), fallbackIncluded: body.includes('Loading related products')}))
}
JS"

