args.command:
/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict'
const response = await fetch('http://localhost:3000/product', {
  headers: {
    rsc: '1',
    'next-router-prefetch': '1',
    'next-router-segment-prefetch': '/product/__PAGE__',
  },
})
assert.equal(response.status, 200)
const bytes = Buffer.from(await response.arrayBuffer())
const fullPrefetch = bytes.toString('utf8')
const shellOffsetId = fullPrefetch.match(/\"a\":\"\\"'$@([a-f0-9]+)"/)?.[1]
assert.ok(shellOffsetId, '"'Expected a staged prefetch response')
const shellOffset = fullPrefetch.match(new RegExp("'`''^${shellOffsetId}:('"\\\\d+)"'$`, '"'m'))?.[1]
assert.ok(shellOffset, 'Expected the app shell byte boundary')
const shell = bytes.subarray(0, Number(shellOffset)).toString('utf8')
assert.ok(shell.includes('Premium Widget'))
assert.ok(shell.includes('A durable widget for everyday projects.'))
assert.ok(shell.includes('Loading related products...'))
for (const product of ['Compact Widget', 'Widget Carry Case']) {
  assert.ok("'!shell.includes(product), `${product} should be outside the default app shell`)
  assert.ok(fullPrefetch.includes(product), `${product} should be available in the expanded prefetch`)
}
console.log('"'Production prefetch checks passed: the default app shell contains the product details and loading fallback; the expanded prefetch contains both related products.')
JS"

